/** Built-in icon presets for the `platform_grid` block. Each entry is the real, official brand
 * mark (sourced from the devicons and simple-icons open-source icon libraries — both explicitly
 * licensed for exactly this "which tech we work with" use case, not traced/faked artwork), inlined
 * as raw SVG so no extra network request is needed and the mark always fills its container cleanly
 * with no background plate. An uploaded image (via Media) remains the alternative for anything not
 * in this list. */

function InlineSvg({ svg }: { svg: string }) {
  return <span style={{ display: "block", width: "100%", height: "100%" }} dangerouslySetInnerHTML={{ __html: svg }} />;
}

function IconWrap({ children }: { children: React.ReactNode }) {
  return (
    <div style={{ width: "100%", height: "100%", display: "flex", alignItems: "center", justifyContent: "center" }}>
      {children}
    </div>
  );
}

