const AWS = <IconWrap><InlineSvg svg={SVG_AWS} /></IconWrap>;
const AZURE = <IconWrap><InlineSvg svg={SVG_AZURE} /></IconWrap>;
const GCP = <IconWrap><InlineSvg svg={SVG_GCP} /></IconWrap>;
const DIGITALOCEAN = <IconWrap><InlineSvg svg={SVG_DIGITALOCEAN} /></IconWrap>;
const KUBERNETES = <IconWrap><InlineSvg svg={SVG_KUBERNETES} /></IconWrap>;
const TERRAFORM = <IconWrap><InlineSvg svg={SVG_TERRAFORM} /></IconWrap>;
const HELM = <IconWrap><InlineSvg svg={SVG_HELM} /></IconWrap>;
const ANSIBLE = <IconWrap><InlineSvg svg={SVG_ANSIBLE} /></IconWrap>;
const PROMETHEUS = <IconWrap><InlineSvg svg={SVG_PROMETHEUS} /></IconWrap>;
const GRAFANA = <IconWrap><InlineSvg svg={SVG_GRAFANA} /></IconWrap>;
const ARGOCD = <IconWrap><InlineSvg svg={SVG_ARGOCD} /></IconWrap>;
const JENKINS = <IconWrap><InlineSvg svg={SVG_JENKINS} /></IconWrap>;
const GITLAB_CI = <IconWrap><InlineSvg svg={SVG_GITLAB_CI} /></IconWrap>;
const NGINX = <IconWrap><InlineSvg svg={SVG_NGINX} /></IconWrap>;
const GITHUB_ACTIONS = <IconWrap><InlineSvg svg={SVG_GITHUB_ACTIONS} /></IconWrap>;
const DOCKER = <IconWrap><InlineSvg svg={SVG_DOCKER} /></IconWrap>;

export const PLATFORM_ICON_PRESETS: Record<string, { label: string; node: React.ReactNode }> = {
  aws: { label: "AWS", node: AWS },
  azure: { label: "Azure", node: AZURE },
  gcp: { label: "Google Cloud", node: GCP },
  digitalocean: { label: "DigitalOcean", node: DIGITALOCEAN },
  kubernetes: { label: "Kubernetes", node: KUBERNETES },
  terraform: { label: "Terraform", node: TERRAFORM },
  helm: { label: "Helm", node: HELM },
  ansible: { label: "Ansible", node: ANSIBLE },
  prometheus: { label: "Prometheus", node: PROMETHEUS },
  grafana: { label: "Grafana", node: GRAFANA },
  argocd: { label: "Argo CD", node: ARGOCD },
  jenkins: { label: "Jenkins", node: JENKINS },
  gitlab_ci: { label: "GitLab CI", node: GITLAB_CI },
  nginx: { label: "Nginx", node: NGINX },
  github_actions: { label: "GitHub Actions", node: GITHUB_ACTIONS },
  docker: { label: "Docker", node: DOCKER },
};

export function PlatformIcon({ iconKey, iconUrl }: { iconKey?: string | null; iconUrl?: string | null }) {
  if (iconKey && PLATFORM_ICON_PRESETS[iconKey]) {
    return <>{PLATFORM_ICON_PRESETS[iconKey].node}</>;
  }
  if (iconUrl) {
    return (
      <IconWrap>
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img src={iconUrl} alt="" style={{ width: "100%", height: "100%", objectFit: "contain" }} />
      </IconWrap>
    );
  }
  return (
    <IconWrap>
      <i className="ti ti-cloud" style={{ fontSize: "60%", color: "rgba(120,120,120,0.4)" }} />
    </IconWrap>
  );
}
